- Nimanya? Ni lukhu, esyuko syabatsanga khu Nyasaye wa manyu, khulwa omundu omulala. (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
