- Naboola: "Fwe ndi mulayi okhushila ye; wandumba khumuliro, naye wandumba khulutaka." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
