- Naboola: "Khu tsibala tsanje! Mulole? Ne ndi khubulolero butong'ene khukhuma Omwami wange, naye yandiha." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- Ne baboola: "Lwasi siahuluusibwa akamenyi khukhuma Omwami we?" Boola: "Eyo niyingila." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
